import * as THREE from './three.module.min.js';
const canvas=document.querySelector('#ocean'),reduced=matchMedia('(prefers-reduced-motion: reduce)');
let paused=reduced.matches,p=0,target=0,t=0,last=performance.now();
const button=document.querySelector('#motion');
