const geo=new THREE.IcosahedronGeometry(1.47,2);const pos=geo.attributes.position;for(let i=0;i<pos.count;i++){const x=pos.getX(i),y=pos.getY(i),z=pos.getZ(i);const n=1+.13*Math.sin(x*4.1+y*3.2)*Math.cos(z*3.7)+.08*Math.sin(y*7+z*3);pos.setXYZ(i,x*n*.84,y*n*1.23,z*n*.8)}geo.computeVertexNormals();
const material=new THREE.MeshPhysicalMaterial({color:0x4d8898,metalness:.72,roughness:.29,flatShading:true,clearcoat:.85,clearcoatRoughness:.2});rock.add(new THREE.Mesh(geo,material));
const edges=new THREE.LineSegments(new THREE.EdgesGeometry(geo,27),new THREE.LineBasicMaterial({color:0x87e6e9,transparent:true,opacity:.12}));rock.add(edges);
